-- =====================================================================
-- ZORION SAÚDE — RESTAURAR OS CADASTROS QUE O MERGE POR NOME ABSORVEU
-- =====================================================================
-- O merge antigo agrupou só pelo NOME e juntou apresentações diferentes
-- (25 MG com 100 MG, gotas com comprimido, ampolas de 0,9% com 20%...).
-- Este script devolve cada cadastro absorvido, com os lotes e a quantidade
-- que existem HOJE na tabela "Lote" (não inventa estoque).
--
-- Fonte: backup Zorion_ANTES_MERGE_2026-10-31_081003.dump (estado de 31/10,
-- 08:10, antes do merge). Só os 96 cadastros dos 42 nomes que o merge tocou
-- são considerados — nenhum outro é alterado.
--
-- É idempotente: cadastro que já está visível não é tocado; lote que já
-- está no cadastro certo não é movido. Rodar duas vezes não muda nada.
--
-- Faça backup antes e rode com o aplicativo fechado:
--   psql -h HOST -U postgres -d Zorion -v ON_ERROR_STOP=1 \
--        -f 2026-10-31_RESTAURAR_MERGE_POR_NOME.sql
--
-- Tudo dentro de UMA transação. Se o total de estoque mudar, ele ABORTA.
-- =====================================================================

BEGIN;

-- 0. fotografia dos totais ANTES (para provar que nada muda no total)
CREATE TEMP TABLE totais_antes ON COMMIT DROP AS
SELECT coalesce(sum(coalesce(estoque_atual,0)),0)    AS central,
       coalesce(sum(coalesce(estoque_satelite,0)),0) AS satelite
  FROM "Medicamento" WHERE deleted_at IS NULL;

-- 1. snapshot do estado pré-merge -------------------------------------
CREATE TEMP TABLE snap_med (j jsonb) ON COMMIT DROP;
