-07-31"}, {"med_id": "587971d4-c24d-49b0-815a-ca953382d869", "lote_id": "f9bf2684-0833-4b74-bb82-160805a73f32", "numero_lote": "BPMID25012A", "data_validade": "2027-04-30"}, {"med_id": "220f4694-4b0b-481a-9a1a-9218b4bcb34f", "lote_id": "fac18c35-9f3e-44e4-87eb-1e69226f676d", "numero_lote": "1279689", "data_validade": "2028-03-12"}, {"med_id": "a3db1979-832e-454a-900d-fbd1db43c1f0", "lote_id": "fad60f5c-d617-483d-93e6-a7fe0aeb0755", "numero_lote": "4T4026", "data_validade": "2027-04-30"}, {"med_id": "c9bd5445-ae91-40e5-924e-42dcc825eb57", "lote_id": "fb0236d5-7028-4fab-9d1b-6f38a1c85f3d", "numero_lote": "50036211", "data_validade": "2027-12-31"}, {"med_id": "220f4694-4b0b-481a-9a1a-9218b4bcb34f", "lote_id": "fd694b4f-010c-4215-8de0-6d51c45bd821", "numero_lote": "40906656", "data_validade": "2027-01-31"}, {"med_id": "db801763-cfb8-44d9-b46b-6738874c850d", "lote_id": "fe42f65a-417d-4e79-b831-0ada08c25acd", "numero_lote": "5J5949", "data_validade": "2028-02-28"}]$json$::jsonb) x;

CREATE TEMP TABLE snap_ids ON COMMIT DROP AS
SELECT (j->>'id') AS id FROM snap_med;

-- 2. quem está invisível hoje (sumiu do cadastro) ----------------------
CREATE TEMP TABLE restaurados ON COMMIT DROP AS
SELECT s.j->>'id'                 AS id,
       s.j->>'nome'               AS nome,
       upper(btrim(s.j->>'nome')) AS nome_norm,
       s.j->>'concentracao'       AS concentracao,
       s.j->>'apresentacao'       AS apresentacao,
       coalesce((s.j->>'estoque_satelite')::int, 0) AS sat_snapshot
  FROM snap_med s
 WHERE NOT EXISTS (
       SELECT 1 FROM "Medicamento" m
        WHERE m.id = s.j->>'id'
          AND m.deleted_at IS NULL
          AND coalesce(m.ativo, false)
 );

SELECT '=== CADASTROS QUE SERAO RESTAURADOS (estado de hoje) ===' AS etapa;
SELECT r.nome, r.concentracao, r.apresentacao
  FROM restaurados r
 ORDER BY r.nome, r.concentracao, r.apresentacao;

-- 2a. satélite que vive só no cadastro (sem lote): em que sobrevivente
--     ele está hoje? Precisa ser único para poder ser devolvido.
CREATE TEMP TABLE sat_mover ON COMMIT DROP AS
SELECT r.id, r.sat_snapshot, s.id AS sobrevivente_id
  FROM restaurados r
  JOIN LATERAL (
        SELECT m.id
          FROM "Medicamento" m
         WHERE upper(btrim(m.nome)) = r.nome_norm
           AND m.deleted_at IS NULL
           AND coalesce(m.ativo, false)
           AND m.id NOT IN (SELECT id FROM restaurados)
         LIMIT 2
       ) s ON true
 WHERE r.sat_snapshot > 0
   AND NOT EXISTS (SELECT 1 FROM snap_lote sl WHERE sl.med_id = r.id);

DO $$
DECLARE amb integer;
BEGIN
    SELECT count(*) INTO amb FROM (
        SELECT r.id
          FROM restaurados r
         WHERE r.sat_snapshot > 0
           AND NOT EXISTS (SELECT 1 FROM snap_lote sl WHERE sl.med_id = r.id)
           AND (SELECT count(*) FROM "Medicamento" m
                 WHERE upper(btrim(m.nome)) = r.nome_norm
                   AND m.deleted_at IS NULL AND coalesce(m.ativo,false)
                   AND m.id NOT IN (SELECT id FROM restaurados)) <> 1
    ) x;
    IF amb > 0 THEN
        RAISE EXCEPTION 'ABORTADO: % cadastro(s) com satélite sem lote e sobrevivente ambíguo. Nada foi gravado.', amb;
    END IF;
END $$;

-- 3. reativar os que ainda existem (soft delete do merge) --------------
UPDATE "Medicamento" m
   SET ativo = true,
       deleted_at = NULL
  FROM restaurados r
 WHERE m.id = r.id;

-- 4. recriar os que foram apagados de fato -----------------------------
INSERT INTO "Medicamento"
SELECT (jsonb_populate_record(NULL::"Medicamento", s.j)).*
  FROM snap_med s
 WHERE s.j->>'id' IN (SELECT id FROM restaurados)
   AND NOT EXISTS (SELECT 1 FROM "Medicamento" m WHERE m.id = s.j->>'id');

-- 5. devolver os lotes ao cadastro de origem ---------------------------
CREATE TEMP TABLE mov ON COMMIT DROP AS
SELECT l.id                 AS lote_id,
       l.medicamento_id     AS atual,
       sl.med_id            AS destino,
       coalesce(l.quantidade_atual, 0)    AS qa,
       coalesce(l.quantidade_satelite, 0) AS qs
  FROM "Lote" l
  JOIN snap_lote sl ON sl.lote_id = l.id
 WHERE l.medicamento_id IS DISTINCT FROM sl.med_id
   AND sl.med_id IN (SELECT id FROM restaurados);

SELECT '=== LOTES DEVOLVIDOS AO CADASTRO DE ORIGEM ===' AS etapa;
SELECT count(*) AS lotes, coalesce(sum(qa),0) AS central, coalesce(sum(qs),0) AS satelite
  FROM mov;

UPDATE "Lote" l
   SET medicamento_id = m.destino
  FROM mov m
 WHERE l.id = m.lote_id;

-- 6. central = soma dos lotes (nos cadastros que o merge tocou) --------
UPDATE "Medicamento" m
   SET estoque_atual = coalesce((
           SELECT sum(coalesce(l.quantidade_atual,0))
             FROM "Lote" l WHERE l.medicamento_id = m.id AND l.deleted_at IS NULL), 0)
 WHERE m.id IN (SELECT id FROM snap_ids);

-- 7. satélite: acompanha os lotes que voltaram -------------------------
UPDATE "Medicamento" m
   SET estoque_satelite = greatest(0, coalesce(m.estoque_satelite,0) - d.qs)
  FROM (SELECT atual AS id, sum(qs) AS qs FROM mov GROUP BY atual) d
 WHERE m.id = d.id AND d.qs > 0;

UPDATE "Medicamento" m
   SET estoque_satelite = coalesce(m.estoque_satelite,0) + d.qs
  FROM (SELECT destino AS id, sum(qs) AS qs FROM mov GROUP BY destino) d
 WHERE m.id = d.id AND d.qs > 0;

-- 7a. satélite que só existia no cadastro: o cadastro restaurado já está
--     com o valor dele (o merge não zera o campo). Retira o valor do
--     sobrevivente, que ficou com a soma, para não duplicar.
UPDATE "Medicamento" m
   SET estoque_satelite = greatest(0, coalesce(m.estoque_satelite,0) - s.sat_snapshot)
  FROM sat_mover s
 WHERE m.id = s.sobrevivente_id;

-- 8. conferência: o total não pode mudar -------------------------------
DO $$
DECLARE
    antes_c int; antes_s int; depois_c int; depois_s int;
BEGIN
    SELECT central, satelite INTO antes_c, antes_s FROM totais_antes;
    SELECT coalesce(sum(coalesce(estoque_atual,0)),0),
           coalesce(sum(coalesce(estoque_satelite,0)),0)
      INTO depois_c, depois_s
      FROM "Medicamento" WHERE deleted_at IS NULL;

    IF depois_c <> antes_c OR depois_s <> antes_s THEN
        RAISE EXCEPTION
          'ABORTADO: o total mudaria (central % -> %, satelite % -> %). Nada foi gravado.',
          antes_c, depois_c, antes_s, depois_s;
    END IF;

    RAISE NOTICE 'Conferencia OK: central % e satelite % preservados', depois_c, depois_s;
END $$;

-- 9. resultado ---------------------------------------------------------
SELECT '=== CONFERENCIA FINAL ===' AS etapa;
SELECT count(*) FILTER (WHERE m.deleted_at IS NULL AND coalesce(m.ativo,false)) AS cadastros_visiveis
  FROM "Medicamento" m WHERE m.id IN (SELECT id FROM snap_ids);

SELECT 'central' AS item, coalesce(sum(coalesce(estoque_atual,0)),0) AS valor
  FROM "Medicamento" WHERE deleted_at IS NULL
UNION ALL
SELECT 'satelite', coalesce(sum(coalesce(estoque_satelite,0)),0)
  FROM "Medicamento" WHERE deleted_at IS NULL;

COMMIT;
